result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/apply_payments.py", "content": """"Payments-to-invoices application engine.

Given open invoices per customer and incoming payments, applies targeted
payments to their referenced invoice first, then applies any remaining
amount oldest-invoice-first with partial application allowed. Any excess
becomes customer credit; an invoice balance never goes negative.
"""

from dataclasses import dataclass, field
from typing import Dict, List, Optional


@dataclass
class Invoice:
    id: str
    date: str  # ISO date string; lexicographic order == chronological
    balance_cents: int


@dataclass
class Payment:
    customer: str
    amount_cents: int
    invoice_id: Optional[str] = None  # optional targeting


@dataclass
class ApplicationResult:
    """Per-payment report: (invoice_id, applied_cents) pairs + leftover credit."""
    payment: Payment
    applications: List[tuple] = field(default_factory=list)
    leftover_credit_cents: int = 0


def _open_invoices_by_customer(invoices):
    by_customer: Dict[str, List[Invoice]] = {}
    for inv in invoices:
        if inv.balance_cents <= 0:
            continue  # already settled / credit-note; never overpay it
        by_customer.setdefault(getattr(inv, "customer", None) or _customer_of(inv), []).append(inv)
    for lst in by_customer.values():
        lst.sort(key=lambda i: (i.date, i.id))
    return by_customer


def _customer_of(invoice):
    # Invoices carry their customer via the bucketing done by the caller;
    # see apply_payments_to_invoices for the grouped-input path.
    return invoice._customer  # set below when grouping flat inputs


def apply_payments_to_invoices(payments: List[Payment], invoices: List[Invoice]):
    """Apply payments to invoices.

    ``invoices`` may be either a flat list of Invoice objects that each carry
    a ``customer`` attribute, or a dict mapping customer -> list[Invoice].
    Returns a list of ApplicationResult, one per input payment, in order.
    """
    if isinstance(invoices, dict):
        buckets = {
            cust: sorted([i for i in lst if i.balance_cents > 0],
                         key=lambda i: (i.date, i.id))
            for cust, lst in invoices.items()
        }
    else:
        buckets: Dict[str, List[Invoice]] = {}
        for inv in invoices:
            inv._customer = getattr(inv, "customer", "")
            if inv.balance_cents <= 0:
                continue
            buckets.setdefault(inv._customer, []).append(inv)
        for lst in buckets.values():
            lst.sort(key=lambda i: (i.date, i.id))

    report: List[ApplicationResult] = []
    for pay in payments:
        result = ApplicationResult(payment=pay)
        remaining = pay.amount_cents
        open_list = buckets.get(pay.customer)

        def apply_to(inv):
            nonlocal remaining
            if remaining <= 0 or inv.balance_cents <= 0:
                return False
            applied = min(remaining, inv.balance_cents)
            inv.balance_cents -= applied
            remaining -= applied
            result.applications.append((inv.id, applied))
            return True

        # 1) Targeted application: the referenced invoice gets paid first,
        #    overriding date order. Never drives it negative.
        if pay.invoice_id is not None and open_list:
            target = next((i for i in open_list if i.id == pay.invoice_id), None)
            if target is not None:
                apply_to(target)

        # 2) Remainder: oldest invoice first, partial application allowed.
        if remaining > 0 and open_list:
            for inv in list(open_list):
                if remaining <= 0:
                    break
                apply_to(inv)

        # 3) Excess becomes customer credit, never a negative balance.
        result.leftover_credit_cents = remaining
        report.append(result)

    return report
